<script lang="ts">
 import {SPECIALTIES,DOMAINS,DOMAIN_LABELS} from '$lib/medicine/catalogue';
 import {specialtyScore,type State} from '$lib/medicine/study';
 export let state:State;
 export let onchoose:(id:string)=>void;
 const band=(score:number|undefined)=>score===undefined?'unknown':score<8?'weak':score<12?'help':score<16?'developing':score<19?'independent':'robust';
 const groups=[...new Set(SPECIALTIES.map(s=>s.group))];
 const groupNames:Record<string,string>={'Clinical breadth':'Hausärztliche Breite','Internal medicine':'Innere Medizin','Life stages':'Lebensphasen','Surgical care':'Operative Fächer','Clinical specialties':'Weitere klinische Fächer','Acute & supportive care':'Akut- und unterstützende Versorgung','Diagnostics & therapeutics':'Diagnostik und Therapie'};
</script>
<section class="clinical-map" aria-label="Klinische Fachlandkarte"><div class="map-heading"><h2>Die ganze Klinik im Blick.</h2><p>Farbe = beobachtete Fallleistung, nicht Beherrschung eines ganzen Faches. Der Wert mittelt bis zu fünf vollständig bewertete Fallanteile.</p></div>
 {#each groups as group}<h3>{groupNames[group]}</h3><div class="tiles">{#each SPECIALTIES.filter(s=>s.group===group) as s}{@const summary=state.specialties[s.id]}{@const score=specialtyScore(state,s.id)}<button class={`band-${band(score)}`} on:click={()=>onchoose(s.id)} aria-label={`Fall aus ${s.title} auswählen`}><span>{s.title}</span><strong>{score===undefined?'—':score.toFixed(1)}<small>/20</small></strong><small>{summary?.cases??0} {summary?.cases===1?'Fall':'Fälle'} · {(summary?.scores.length??0)<3?'begrenzte Stichprobe':'Fallbeobachtungen'}</small><div class="domains">{#each DOMAINS as d}<i class={`band-${band(summary?.lastRatings[d]===undefined?undefined:summary.lastRatings[d]!*5)}`} title={`${DOMAIN_LABELS[d]}: ${summary?.lastRatings[d]??'nicht geprüft'}/4`}></i>{/each}</div></button>{/each}</div>{/each}
 <div class="legend"><span><i class="band-unknown"></i>Ungeprüft / Teilbewertung</span><span><i class="band-weak"></i>Unsicher 0–7</span><span><i class="band-help"></i>Mit Hilfe 8–11</span><span><i class="band-developing"></i>In Entwicklung 12–15</span><span><i class="band-independent"></i>Selbstständig 16–18</span><span><i class="band-robust"></i>Belastbar im Fall 19–20</span></div><p class="note">Die fünf Streifen zeigen die zuletzt geprüften Bereiche: Anamnese/Untersuchung, Einordnung, Diagnostik, Behandlung und Sicherheit. Grau bleibt ungeprüft.</p>
</section>
