 .clinical-map{color:#edf0f6}.map-heading{max-width:75ch;margin-bottom:28px}h2{font-size:1.5rem;letter-spacing:-.02em;margin:0 0 10px}p{color:#adb7c9;line-height:1.6;font-size:.85rem}h3{font-size:.9rem;color:#d4daE6;margin:26px 0 10px}.tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:9px}.tiles button{font:inherit;min-height:150px;display:flex;flex-direction:column;justify-content:space-between;gap:9px;text-align:left;color:#f5f5fa;border:1px solid transparent;border-radius:10px;padding:14px;cursor:pointer;touch-action:manipulation}.tiles span{font-size:.84rem;line-height:1.35}.tiles strong{font-size:1.65rem;font-variant-numeric:tabular-nums;font-weight:700}.tiles strong small{font-size:.75rem;margin-left:4px}.tiles>button>small{font-size:.64rem;color:#e2e6ed;line-height:1.4}.band-unknown{background:#303846}.band-weak{background:#7b3f51}.band-help{background:#86551f}.band-developing{background:#736426}.band-independent{background:#286878}.band-robust{background:#256b50}.domains{display:flex;gap:3px}.domains i{height:6px;flex:1;border:1px solid #acb6c570;border-radius:2px}.legend{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px;font-size:.7rem;color:#b7c0d0}.legend>span{display:flex;gap:5px;align-items:center}.legend i{width:10px;height:10px;border-radius:2px}.note{font-size:.73rem}.tiles button:focus-visible{outline:2px solid #d2caff;outline-offset:3px}@media(hover:hover)and(pointer:fine){.tiles button:hover{border-color:#d5cfff}}@media(max-width:450px){.tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.tiles button{padding:11px;min-height:160px}.tiles span{font-size:.8rem}}
</style>
